rss.channel:
{{ if eq .Title .Site.Title }}{{ .Site.Title }}{{ else }}{{ with .Title }}{{.}} on {{ end }}{{ .Site.Title }}{{ end }}
{{ .Permalink }}
Neueste Comics und News von {{ .Site.Title }}
{{ .Site.LanguageCode }}
{{ with .OutputFormats.Get "RSS" }}
    {{ printf "" .Permalink .MediaType | safeHTML }}
{{ end }}
{{ range first 20 (where .Site.RegularPages "Section" "in" (slice "comics" "news")).ByDate.Reverse }}


  {{ .Title }}
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
  {{ .Permalink }}

    {{- if .Content -}}
        {{- .Content | html -}}
    {{- else -}}
        {{/* Falls mal kein Text da ist, zeigen wir nur den Titel */}}
        Neuer Beitrag auf Schwemme Comics!
    {{- end -}}


{{ end }}
